page.script:
function PrintThisDiv(id) {
var HTMLContent = document.getElementById(id);
var Popup = window.open('about:blank', id, 'width=1360,height=800');

Popup.document.writeln('
');
Popup.document.writeln("");

Popup.document.writeln('');
Popup.document.writeln(HTMLContent.innerHTML);
Popup.document.writeln('');
Popup.document.close();
Popup.focus();
Popup.print();


 }



function exportTableToExcel(table,name){
      $(table).table2excel({
    exclude: ".excludeThisClass",
    name: "IR17",
    filename: name + ".xls", // do include extension
    preserveColors:true // set to true if you want background colors and font colors preserved
});
}

